insert into public.ref_exercises (id, name, category, pattern, equipment, primary_muscles, tracking, load_convention, data) values
  ('barbell-back-squat', 'Barbell back squat', 'compound', 'squat', array['barbell', 'rack']::text[], array['quads', 'glutes']::text[], 'weight_reps', 'total', '{"id":"barbell-back-squat","name":"Barbell back squat","aliases":["back squat","squat","high-bar squat","low-bar squat"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["adductors","hamstrings","lower_back","abs"],"pattern":"squat","equipment":["barbell","rack"],"difficulty":2,"tracking":"weight_reps","load":"total","stresses":["knee","hip","lower_back"],"mainLift":true,"increment":{"kg":2.5,"lb":5},"setup":"Set the bar in the rack at about upper-chest height. Step under it so it rests across your upper back, grip just outside your shoulders, then stand it up and take two or three small steps back to a shoulder-width stance with toes turned slightly out.","execution":"Brace your midsection, then bend at the hips and knees together and sit down between your heels until your thighs are at least parallel or as deep as you can keep your back neutral. Drive the floor away to stand back up, keeping the bar over the middle of your feet.","cues":["Big breath and brace before each rep","Knees track over your toes","Whole foot stays planted","Chest and hips rise together"],"mistakes":["Heels lifting or weight shifting to the toes","Knees caving inward on the way up","Hips shooting up first so the lift turns into a good-morning"],"substitutions":["barbell-front-squat","hack-squat","leg-press","goblet-squat","bodyweight-squat"]}'::jsonb),
  ('barbell-front-squat', 'Barbell front squat', 'compound', 'squat', array['barbell', 'rack']::text[], array['quads', 'glutes']::text[], 'weight_reps', 'total', '{"id":"barbell-front-squat","name":"Barbell front squat","aliases":["front squat"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["upper_back","abs","adductors"],"pattern":"squat","equipment":["barbell","rack"],"difficulty":3,"tracking":"weight_reps","load":"total","stresses":["knee","wrist","lower_back"],"mainLift":true,"increment":{"kg":2.5,"lb":5},"setup":"Set the bar at shoulder height. Step in so it sits on the front of your shoulders against your throat, fingers under the bar just outside the shoulders (or arms crossed), elbows high. Unrack and step back to a shoulder-width stance.","execution":"Keep the elbows up and torso tall as you squat straight down between your knees. Go as deep as you can while the upper back stays upright, then stand up by pushing through the whole foot.","cues":["Elbows point forward, not down","Stay tall through the upper back","Sit down, not back"],"mistakes":["Elbows dropping so the bar rolls forward","Gripping the bar tightly with stiff wrists instead of letting it sit on the shoulders","Rounding the upper back out of the bottom"],"substitutions":["barbell-back-squat","goblet-squat","hack-squat","bodyweight-squat"]}'::jsonb),
  ('goblet-squat', 'Goblet squat', 'compound', 'squat', array['dumbbell']::text[], array['quads', 'glutes']::text[], 'weight_reps', 'total', '{"id":"goblet-squat","name":"Goblet squat","aliases":["dumbbell goblet squat","kettlebell goblet squat"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["adductors","abs","upper_back"],"pattern":"squat","equipment":["dumbbell"],"difficulty":1,"tracking":"weight_reps","load":"total","stresses":["knee"],"mainLift":true,"increment":{"kg":2,"lb":5},"setup":"Hold one dumbbell vertically against your chest with both hands cupping the top end. Stand with feet a little wider than shoulder width, toes slightly out.","execution":"Squat down between your heels, letting your elbows travel inside your knees, until your hips are below your knees or as low as you can control. Pause briefly, then stand up keeping the weight close to your chest.","cues":["Weight stays glued to your chest","Elbows brush the inside of the knees","Tall torso throughout"],"mistakes":["Letting the dumbbell drift away from the body","Cutting depth short","Knees collapsing inward"],"substitutions":["barbell-back-squat","leg-press","bodyweight-squat","bulgarian-split-squat"]}'::jsonb),
