  ('hack-squat', 'Hack squat', 'compound', 'squat', array['machine']::text[], array['quads']::text[], 'weight_reps', 'stack', '{"id":"hack-squat","name":"Hack squat","aliases":["machine hack squat"],"category":"compound","primaryMuscles":["quads"],"secondaryMuscles":["glutes","adductors"],"pattern":"squat","equipment":["machine"],"difficulty":2,"tracking":"weight_reps","load":"stack","stresses":["knee"],"mainLift":true,"increment":{"kg":5,"lb":10},"setup":"Step into the machine with your back against the pad and shoulders under the shoulder pads. Place feet shoulder width in the middle of the platform and release the safety handles.","execution":"Bend your knees and lower yourself until your thighs are at least parallel to the platform. Drive back up while keeping your back flat against the pad.","cues":["Back flat on the pad","Knees follow the toes","Control the bottom position"],"mistakes":["Heels lifting off the platform","Bouncing out of the bottom","Shortening the range as the weight goes up"],"substitutions":["leg-press","barbell-front-squat","goblet-squat","bodyweight-split-squat"]}'::jsonb),
  ('bodyweight-squat', 'Bodyweight squat', 'compound', 'squat', array['bodyweight']::text[], array['quads', 'glutes']::text[], 'reps', 'none', '{"id":"bodyweight-squat","name":"Bodyweight squat","aliases":["air squat","body squat"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["adductors","abs"],"pattern":"squat","equipment":["bodyweight"],"difficulty":1,"tracking":"reps","load":"none","stresses":["knee"],"setup":"Stand with feet shoulder width apart, toes turned out slightly. Reach your arms forward for balance or clasp your hands at your chest.","execution":"Sit down between your heels as deep as you comfortably can with your chest up, then stand back up and squeeze your glutes at the top. Slow the descent down to make it harder.","cues":["Sit between your heels","Knees out over the toes","Stand tall at the top"],"mistakes":["Rising onto the toes","Rounding the back to get deeper","Rushing reps without control"],"substitutions":["goblet-squat","bodyweight-split-squat","leg-press","barbell-back-squat"]}'::jsonb),
  ('bulgarian-split-squat', 'Bulgarian split squat', 'compound', 'lunge', array['dumbbell', 'bench']::text[], array['quads', 'glutes']::text[], 'weight_reps', 'per_hand', '{"id":"bulgarian-split-squat","name":"Bulgarian split squat","aliases":["rear-foot-elevated split squat","RFESS"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["adductors","hamstrings"],"pattern":"lunge","equipment":["dumbbell","bench"],"difficulty":2,"tracking":"weight_reps","load":"per_hand","implements":2,"unilateral":true,"stresses":["knee","hip"],"mainLift":true,"increment":{"kg":2,"lb":5},"setup":"Stand about a stride in front of a bench holding a dumbbell in each hand. Rest the top of your rear foot on the bench and find a front-foot position where your front heel stays down at the bottom.","execution":"Lower straight down until your rear knee nearly touches the floor and the front thigh is about parallel. Push through the front foot to stand back up. Finish all reps on one side, then switch.","cues":["Most of the weight on the front foot","Drop the back knee straight down","Slight forward lean is fine"],"mistakes":["Standing too close to the bench so the front heel lifts","Pushing off the back foot","Front knee caving inward"],"substitutions":["bodyweight-split-squat","dumbbell-reverse-lunge","leg-press","goblet-squat"]}'::jsonb),
  ('dumbbell-reverse-lunge', 'Dumbbell reverse lunge', 'compound', 'lunge', array['dumbbell']::text[], array['quads', 'glutes']::text[], 'weight_reps', 'per_hand', '{"id":"dumbbell-reverse-lunge","name":"Dumbbell reverse lunge","aliases":["reverse lunge","step-back lunge"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","adductors"],"pattern":"lunge","equipment":["dumbbell"],"difficulty":1,"tracking":"weight_reps","load":"per_hand","implements":2,"unilateral":true,"stresses":["knee"],"increment":{"kg":2,"lb":5},"setup":"Stand tall with feet hip width apart and a dumbbell hanging at each side.","execution":"Step one foot back and lower until the back knee is just above the floor and the front shin is roughly vertical. Push through the front heel to return to standing. Complete the reps on one side before switching, or alternate and count each side.","cues":["Long step back","Front heel stays heavy","Torso tall, shoulders down"],"mistakes":["Stepping back too short so the front knee jams forward","Wobbling side to side on a tightrope stance","Slamming the back knee into the floor"],"substitutions":["walking-lunge","bulgarian-split-squat","bodyweight-split-squat","dumbbell-step-up"]}'::jsonb),
  ('walking-lunge', 'Dumbbell walking lunge', 'compound', 'lunge', array['dumbbell']::text[], array['quads', 'glutes']::text[], 'weight_reps', 'per_hand', '{"id":"walking-lunge","name":"Dumbbell walking lunge","aliases":["walking lunge","lunges"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","adductors","calves"],"pattern":"lunge","equipment":["dumbbell"],"difficulty":2,"tracking":"weight_reps","load":"per_hand","implements":2,"unilateral":true,"stresses":["knee"],"increment":{"kg":2,"lb":5},"setup":"Hold a dumbbell at each side and stand at one end of a clear walkway with feet hip width apart.","execution":"Step forward into a lunge until the back knee is just above the floor, then drive through the front foot and bring the back leg through into the next step. Count reps per leg.","cues":["Controlled steps, not a stumble","Front foot flat","Keep hip-width tracks"],"mistakes":["Pushing off the back toes instead of the front foot","Taking very short steps","Letting the dumbbells swing"],"substitutions":["dumbbell-reverse-lunge","bodyweight-split-squat","dumbbell-step-up","leg-press"]}'::jsonb),
  ('dumbbell-step-up', 'Dumbbell step-up', 'compound', 'lunge', array['dumbbell', 'bench']::text[], array['quads', 'glutes']::text[], 'weight_reps', 'per_hand', '{"id":"dumbbell-step-up","name":"Dumbbell step-up","aliases":["step up","box step-up","bench step-up"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","calves"],"pattern":"lunge","equipment":["dumbbell","bench"],"difficulty":1,"tracking":"weight_reps","load":"per_hand","implements":2,"unilateral":true,"stresses":["knee"],"increment":{"kg":2,"lb":5},"setup":"Stand facing a sturdy bench or box about knee height with a dumbbell in each hand. Place one whole foot on top.","execution":"Lean slightly forward and drive through the top foot to stand up onto the box, bringing the other foot up beside it. Step down slowly with the same trailing foot. Finish one side, then switch.","cues":["Drive through the top heel","Minimal push from the bottom foot","Lower down slowly"],"mistakes":["Bouncing off the floor leg","Using a box so high the hips tuck under","Knee drifting inward on the way up"],"substitutions":["dumbbell-reverse-lunge","bulgarian-split-squat","bodyweight-split-squat"]}'::jsonb),
  ('bodyweight-split-squat', 'Bodyweight split squat', 'compound', 'lunge', array['bodyweight']::text[], array['quads', 'glutes']::text[], 'reps', 'none', '{"id":"bodyweight-split-squat","name":"Bodyweight split squat","aliases":["split squat","static lunge"],"category":"compound","primaryMuscles":["quads","glutes"],"secondaryMuscles":["adductors","hamstrings"],"pattern":"lunge","equipment":["bodyweight"],"difficulty":1,"tracking":"reps","load":"none","unilateral":true,"stresses":["knee"],"setup":"Take a long split stance with feet hip width apart side to side. Lift the back heel so you are on the ball of that foot. Hands on hips or hold something for balance.","execution":"Bend both knees to lower straight down until the back knee is just above the floor, then press up through the front foot. Stay in the stance for all reps on one side before switching.","cues":["Straight down, straight up","Front heel stays down","Squeeze the rear glute"],"mistakes":["Narrow stance that kills balance","Leaning far forward over the front knee","Only going a few centimetres deep"],"substitutions":["bulgarian-split-squat","dumbbell-reverse-lunge","bodyweight-squat","walking-lunge"]}'::jsonb),
  ('conventional-deadlift', 'Conventional deadlift', 'compound', 'hinge', array['barbell']::text[], array['hamstrings', 'glutes', 'lower_back']::text[], 'weight_reps', 'total', '{"id":"conventional-deadlift","name":"Conventional deadlift","aliases":["deadlift","barbell deadlift"],"category":"compound","primaryMuscles":["hamstrings","glutes","lower_back"],"secondaryMuscles":["upper_back","forearms","quads","lats"],"pattern":"hinge","equipment":["barbell"],"difficulty":3,"tracking":"weight_reps","load":"total","stresses":["lower_back","hip"],"mainLift":true,"increment":{"kg":2.5,"lb":5},"setup":"Stand with mid-foot under the bar, feet about hip width. Hinge down and grip the bar just outside your legs. Bring your shins to the bar, set a flat back, and pull the slack out of the bar so you feel tight before it leaves the floor.","execution":"Push the floor away and keep the bar dragging up your legs. Once it passes your knees, drive your hips forward to stand tall. Lower it by pushing the hips back first, then bending the knees once the bar is past them.","cues":["Bar stays in contact with your legs","Chest up, lats tight","Push the floor away","Lock out with glutes, not by leaning back"],"mistakes":["Jerking the bar off the floor without tension","Rounding the lower back","Hyperextending at the top"],"substitutions":["romanian-deadlift","dumbbell-romanian-deadlift","barbell-hip-thrust","kettlebell-swing"]}'::jsonb),
  ('romanian-deadlift', 'Romanian deadlift', 'compound', 'hinge', array['barbell']::text[], array['hamstrings', 'glutes']::text[], 'weight_reps', 'total', '{"id":"romanian-deadlift","name":"Romanian deadlift","aliases":["RDL","barbell RDL","stiff-leg deadlift"],"category":"compound","primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["lower_back","forearms","upper_back"],"pattern":"hinge","equipment":["barbell"],"difficulty":2,"tracking":"weight_reps","load":"total","stresses":["lower_back"],"mainLift":true,"increment":{"kg":2.5,"lb":5},"setup":"Start standing with the bar at hip height, either lifted from the floor or taken from a rack, with a shoulder-width overhand grip and feet hip width apart.","execution":"Soften the knees slightly and push your hips straight back, sliding the bar down your thighs while keeping your back flat. Stop when you feel a strong hamstring stretch, usually around mid-shin, then drive the hips forward to stand back up.","cues":["Hips back, not down","Bar close to the legs","Knees soft but fixed","Neutral neck"],"mistakes":["Turning it into a squat by bending the knees more","Chasing depth by rounding the back","Letting the bar drift away from the thighs"],"substitutions":["dumbbell-romanian-deadlift","conventional-deadlift","single-leg-rdl","cable-pull-through","band-romanian-deadlift"]}'::jsonb),
  ('dumbbell-romanian-deadlift', 'Dumbbell Romanian deadlift', 'compound', 'hinge', array['dumbbell']::text[], array['hamstrings', 'glutes']::text[], 'weight_reps', 'per_hand', '{"id":"dumbbell-romanian-deadlift","name":"Dumbbell Romanian deadlift","aliases":["dumbbell RDL","DB RDL"],"category":"compound","primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["lower_back","forearms"],"pattern":"hinge","equipment":["dumbbell"],"difficulty":1,"tracking":"weight_reps","load":"per_hand","implements":2,"stresses":["lower_back"],"mainLift":true,"increment":{"kg":2,"lb":5},"setup":"Stand with feet hip width apart holding a dumbbell in each hand in front of your thighs, palms facing you.","execution":"With a slight knee bend, push your hips back and let the dumbbells slide down the front of your legs until you feel your hamstrings stretch. Keep your back flat, then squeeze your glutes to return to standing.","cues":["Reach your hips toward the wall behind you","Dumbbells brush the legs","Long, flat spine"],"mistakes":["Bending the knees and squatting the weight","Rounding the shoulders forward","Going lower than your back can stay flat"],"substitutions":["romanian-deadlift","single-leg-rdl","band-romanian-deadlift","glute-bridge"]}'::jsonb),
  ('single-leg-rdl', 'Single-leg Romanian deadlift', 'compound', 'hinge', array['dumbbell']::text[], array['hamstrings', 'glutes']::text[], 'weight_reps', 'per_hand', '{"id":"single-leg-rdl","name":"Single-leg Romanian deadlift","aliases":["single-leg RDL","one-leg deadlift","SL RDL"],"category":"compound","primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["lower_back","abs","adductors"],"pattern":"hinge","equipment":["dumbbell"],"difficulty":2,"tracking":"weight_reps","load":"per_hand","implements":1,"unilateral":true,"stresses":["hip","lower_back"],"increment":{"kg":2,"lb":5},"setup":"Stand on one leg with a slight bend in that knee, holding a dumbbell in the opposite hand. Use your free hand on a wall or rack for balance if needed.","execution":"Hinge forward at the standing hip as the free leg reaches straight back, keeping your hips square to the floor. Lower until your torso is close to parallel or you feel a deep hamstring stretch, then drive the hip forward to stand up. Finish one side, then switch.","cues":["Body moves like a see-saw","Hips stay level","Back leg stays in line with the torso"],"mistakes":["Rotating the hip open toward the ceiling","Rounding the back to reach lower","Locking the standing knee straight"],"substitutions":["dumbbell-romanian-deadlift","single-leg-glute-bridge","romanian-deadlift"]}'::jsonb),
