  ('incline-treadmill-walk', 'Incline treadmill walk', 'cardio', 'conditioning', array['cardio_machine']::text[], array['cardio']::text[], 'distance_time', 'none', '{"id":"incline-treadmill-walk","name":"Incline treadmill walk","aliases":["treadmill walk","incline walk"],"category":"cardio","primaryMuscles":["cardio"],"secondaryMuscles":["calves","glutes","hamstrings"],"pattern":"conditioning","equipment":["cardio_machine"],"difficulty":1,"tracking":"distance_time","load":"none","stresses":["ankle"],"setup":"Start the treadmill at a slow walking speed, then raise the incline gradually to a level you can sustain.","execution":"Walk at a brisk pace without holding the handrails, keeping an upright posture. Log distance and time.","cues":["Let go of the rails","Upright posture","Steady breathing"],"mistakes":["Leaning on the handrails","Taking long, heavy strides","Starting at a very steep incline"],"substitutions":["stationary-bike","rowing-machine","jumping-jack"]}'::jsonb),
  ('mountain-climber', 'Mountain climber', 'cardio', 'conditioning', array['bodyweight']::text[], array['cardio', 'abs']::text[], 'duration', 'none', '{"id":"mountain-climber","name":"Mountain climber","aliases":["mountain climbers","running plank"],"category":"cardio","primaryMuscles":["cardio","abs"],"secondaryMuscles":["shoulders","quads"],"pattern":"conditioning","equipment":["bodyweight"],"difficulty":1,"tracking":"duration","load":"none","stresses":["wrist","shoulder"],"setup":"Start in a high plank with hands under your shoulders and body in a straight line.","execution":"Drive one knee toward your chest, then switch legs quickly in a running rhythm while keeping your hips level. Work for the target time.","cues":["Shoulders over hands","Hips stay low","Quick feet"],"mistakes":["Hips bouncing high","Shoulders drifting behind the hands","Feet barely moving"],"substitutions":["burpee","jumping-jack","rowing-machine"]}'::jsonb),
  ('burpee', 'Burpee', 'cardio', 'conditioning', array['bodyweight']::text[], array['full_body', 'cardio']::text[], 'reps', 'none', '{"id":"burpee","name":"Burpee","aliases":["squat thrust"],"category":"cardio","primaryMuscles":["full_body","cardio"],"secondaryMuscles":["chest","quads","shoulders"],"pattern":"conditioning","equipment":["bodyweight"],"difficulty":2,"tracking":"reps","load":"none","stresses":["wrist","knee","shoulder"],"setup":"Stand with feet shoulder width apart and enough clear space around you.","execution":"Squat down, place your hands on the floor, jump or step your feet back to a plank, then jump or step them back in and stand or jump up. Add a push-up only if you can keep good form.","cues":["Step instead of jump to make it easier","Land softly","Steady pace you can repeat"],"mistakes":["Collapsing the hips in the plank","Landing heavily on stiff legs","Going so fast that form falls apart"],"substitutions":["mountain-climber","jumping-jack","rowing-machine"]}'::jsonb),
  ('jumping-jack', 'Jumping jack', 'cardio', 'conditioning', array['bodyweight']::text[], array['cardio']::text[], 'duration', 'none', '{"id":"jumping-jack","name":"Jumping jack","aliases":["star jump","jumping jacks"],"category":"cardio","primaryMuscles":["cardio"],"secondaryMuscles":["calves","shoulders"],"pattern":"conditioning","equipment":["bodyweight"],"difficulty":1,"tracking":"duration","load":"none","stresses":["ankle"],"setup":"Stand tall with feet together and arms at your sides.","execution":"Jump your feet out wide while raising your arms overhead, then jump back to the start. Keep a steady rhythm for the target time. Step side to side for a low-impact version.","cues":["Land softly on the balls of the feet","Rhythm over speed","Arms all the way up"],"mistakes":["Landing flat-footed and heavy","Half-height arm swings","Locking the knees"],"substitutions":["mountain-climber","stationary-bike","burpee"]}'::jsonb),
  ('worlds-greatest-stretch', 'World’s greatest stretch', 'mobility', 'mobility', array['bodyweight']::text[], array['hamstrings', 'glutes', 'upper_back']::text[], 'duration', 'none', '{"id":"worlds-greatest-stretch","name":"World’s greatest stretch","aliases":["WGS","lunge with rotation","spiderman lunge with reach"],"category":"mobility","primaryMuscles":["hamstrings","glutes","upper_back"],"secondaryMuscles":["adductors","quads"],"pattern":"mobility","equipment":["bodyweight"],"difficulty":1,"tracking":"duration","load":"none","unilateral":true,"stresses":[],"setup":"Step one foot forward into a long lunge and place both hands on the floor inside the front foot.","execution":"Sink the hips toward the floor, then rotate and reach the inside arm toward the ceiling, following it with your eyes. Return the hand and gently straighten the front leg for a hamstring stretch. Repeat for the target time, then switch sides.","cues":["Long lunge","Breathe into each position","Rotate through the upper back"],"mistakes":["Rushing through the positions","Letting the back knee collapse inward","Forcing range that hurts"],"substitutions":["half-kneeling-hip-flexor-stretch","thoracic-rotation","cat-cow"]}'::jsonb),
  ('cat-cow', 'Cat-cow', 'mobility', 'mobility', array['bodyweight']::text[], array['lower_back', 'upper_back']::text[], 'duration', 'none', '{"id":"cat-cow","name":"Cat-cow","aliases":["cat camel","spinal flexion-extension"],"category":"mobility","primaryMuscles":["lower_back","upper_back"],"secondaryMuscles":["abs"],"pattern":"mobility","equipment":["bodyweight"],"difficulty":1,"tracking":"duration","load":"none","stresses":[],"setup":"Start on hands and knees with hands under shoulders and knees under hips.","execution":"Slowly round your spine toward the ceiling while tucking your chin and tailbone, then reverse by letting your belly drop and lifting your chest and tailbone. Move with your breath for the target time.","cues":["Move one segment at a time","Breathe out to round, in to arch","Smooth and slow"],"mistakes":["Moving only at the neck","Forcing the end ranges","Rushing the movement"],"substitutions":["thoracic-rotation","worlds-greatest-stretch","band-shoulder-dislocate"]}'::jsonb),
  ('thoracic-rotation', 'Thoracic rotation', 'mobility', 'mobility', array['bodyweight']::text[], array['upper_back']::text[], 'reps', 'none', '{"id":"thoracic-rotation","name":"Thoracic rotation","aliases":["open book","quadruped T-spine rotation","thread the needle"],"category":"mobility","primaryMuscles":["upper_back"],"secondaryMuscles":["obliques","shoulders"],"pattern":"mobility","equipment":["bodyweight"],"difficulty":1,"tracking":"reps","load":"none","unilateral":true,"stresses":[],"setup":"Kneel on all fours, then sit your hips slightly back toward your heels. Place one hand behind your head.","execution":"Rotate that elbow down toward the opposite wrist, then open up and rotate it toward the ceiling, following with your eyes. Keep the hips still. Finish the reps on one side, then switch.","cues":["Hips stay back and still","Breathe out as you open","Follow the elbow with your eyes"],"mistakes":["Rotating from the lower back","Rushing","Shrugging the shoulder up"],"substitutions":["cat-cow","worlds-greatest-stretch","band-shoulder-dislocate"]}'::jsonb),
  ('half-kneeling-hip-flexor-stretch', 'Half-kneeling hip flexor stretch', 'mobility', 'mobility', array['bodyweight']::text[], array['quads']::text[], 'duration', 'none', '{"id":"half-kneeling-hip-flexor-stretch","name":"Half-kneeling hip flexor stretch","aliases":["kneeling hip flexor stretch","couch stretch (easy)"],"category":"mobility","primaryMuscles":["quads"],"secondaryMuscles":["abs","glutes"],"pattern":"mobility","equipment":["bodyweight"],"difficulty":1,"tracking":"duration","load":"none","unilateral":true,"stresses":["knee"],"setup":"Kneel on one knee on a soft surface with the other foot flat in front, both knees at about 90°.","execution":"Tuck your pelvis under by squeezing the glute of the kneeling leg, then shift gently forward until you feel a stretch at the front of that hip. Hold for the target time, breathing slowly, then switch sides.","cues":["Squeeze the back glute","Tall torso","Small shift, big stretch"],"mistakes":["Arching the lower back to go further","Kneeling on a hard floor with no padding","Lunging too far forward"],"substitutions":["worlds-greatest-stretch","cat-cow","thoracic-rotation"]}'::jsonb),
  ('band-shoulder-dislocate', 'Band shoulder pass-through', 'mobility', 'mobility', array['band']::text[], array['shoulders', 'upper_back']::text[], 'reps', 'none', '{"id":"band-shoulder-dislocate","name":"Band shoulder pass-through","aliases":["band dislocates","shoulder pass-through","band pass-over"],"category":"mobility","primaryMuscles":["shoulders","upper_back"],"secondaryMuscles":["rear_delts"],"pattern":"mobility","equipment":["band"],"difficulty":1,"tracking":"reps","load":"none","stresses":["shoulder"],"setup":"Hold a light band in front of your hips with a wide overhand grip, arms straight.","execution":"Keeping your arms straight, raise the band overhead and continue behind you as far as is comfortable, then bring it back to the front. Widen your grip if it feels tight.","cues":["Wide grip, straight arms","Ribs stay down","Only go as far as is comfortable"],"mistakes":["Gripping too narrow and forcing it","Bending the elbows","Arching the lower back to get the band over"],"substitutions":["thoracic-rotation","cat-cow","worlds-greatest-stretch"]}'::jsonb)
