insert into public.ref_recipes (id, name, meal, servings, data) values
  ('skyr-berry-oat-bowl', 'Skyr berry bowl with oats', 'breakfast', 1, '{"id":"skyr-berry-oat-bowl","name":"Skyr berry bowl with oats","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":200,"display":"200 g (about ¾ cup)"},{"ingredientId":"blueberries","grams":75,"display":"½ cup","prep":"fresh or thawed"},{"ingredientId":"oats-dry","grams":30,"display":"⅓ cup","prep":"dry"},{"ingredientId":"chia-seeds","grams":6,"display":"½ tbsp"},{"ingredientId":"honey","grams":7,"display":"1 tsp","optional":true}],"steps":["Spoon the skyr into a bowl and stir until smooth.","Scatter the oats and chia seeds over the top.","Add the berries and drizzle with honey if you like it sweeter."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"blueberries","alternatives":["strawberries","banana"]}]}'::jsonb),
  ('overnight-oats-banana', 'Banana overnight oats', 'breakfast', 1, '{"id":"overnight-oats-banana","name":"Banana overnight oats","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"milk","grams":150,"display":"⅔ cup"},{"ingredientId":"greek-yogurt-0","grams":100,"display":"100 g"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"},{"ingredientId":"banana","grams":60,"display":"½ banana","prep":"sliced"}],"steps":["Stir the oats, milk, yogurt and chia seeds together in a jar.","Cover and refrigerate for at least 4 hours or overnight.","Top with sliced banana before eating. Loosen with a splash of milk if it is too thick."],"substitutions":[{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]},{"ingredientId":"greek-yogurt-0","alternatives":["skyr-plain","soy-yogurt"]}],"notes":"Keeps for 2 days in the fridge, so make two jars at once."}'::jsonb),
  ('veggie-eggs-on-rye', 'Spinach & tomato eggs on rye', 'breakfast', 1, '{"id":"veggie-eggs-on-rye","name":"Spinach & tomato eggs on rye","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":5,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"diced"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Warm the oil in a non-stick pan over medium heat and wilt the spinach with the tomato for 1 minute.","Beat the eggs with salt and pepper, pour into the pan and stir gently until just set.","Toast the rye bread and pile the eggs on top."],"substitutions":[{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","rye-crispbread"]},{"ingredientId":"egg","alternatives":["tofu-firm"]}]}'::jsonb),
  ('tofu-scramble-peppers', 'Tofu scramble with peppers', 'breakfast', 1, '{"id":"tofu-scramble-peppers","name":"Tofu scramble with peppers","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"tofu-firm","grams":150,"display":"150 g","prep":"drained, crumbled"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"diced"},{"ingredientId":"onion","grams":40,"display":"⅓ onion","prep":"diced"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":3,"display":"turmeric, paprika, salt & pepper"},{"ingredientId":"wholewheat-bread","grams":64,"display":"2 slices","prep":"toasted"}],"steps":["Fry the onion and pepper in the oil for 4 minutes until soft.","Crumble in the tofu, add the spices and cook for 3 minutes, stirring.","Fold through the spinach until wilted and serve with toast."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["egg"]},{"ingredientId":"wholewheat-bread","alternatives":["rye-bread"]}]}'::jsonb),
  ('peanut-banana-porridge', 'Peanut butter banana porridge', 'breakfast', 1, '{"id":"peanut-banana-porridge","name":"Peanut butter banana porridge","meal":"breakfast","servings":1,"prepMinutes":2,"cookMinutes":5,"ingredients":[{"ingredientId":"oats-dry","grams":60,"display":"¾ cup","prep":"dry"},{"ingredientId":"soy-drink","grams":250,"display":"1 cup"},{"ingredientId":"banana","grams":100,"display":"1 small banana","prep":"sliced"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"}],"steps":["Simmer the oats in the soy drink for 4–5 minutes, stirring, until creamy.","Stir in half the banana to sweeten.","Top with the rest of the banana and the peanut butter."],"substitutions":[{"ingredientId":"soy-drink","alternatives":["milk","oat-drink"]},{"ingredientId":"peanut-butter","alternatives":["tahini","almonds"]}]}'::jsonb),
  ('cottage-cheese-rye-toast', 'Cottage cheese & tomato rye toast', 'breakfast', 1, '{"id":"cottage-cheese-rye-toast","name":"Cottage cheese & tomato rye toast","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":2,"ingredients":[{"ingredientId":"rye-bread","grams":64,"display":"2 slices","prep":"toasted"},{"ingredientId":"cottage-cheese","grams":150,"display":"⅔ cup"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"sliced"},{"ingredientId":"cucumber","grams":40,"display":"5 cm piece","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"black pepper, dill or chives"}],"steps":["Toast the rye bread.","Spread the cottage cheese on the toast.","Top with tomato and cucumber slices and season with pepper and herbs."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","hummus"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","rye-crispbread"]}]}'::jsonb),
  ('chicken-rice-broccoli-bowl', 'Garlic chicken, rice & broccoli bowls', 'lunch', 2, '{"id":"chicken-rice-broccoli-bowl","name":"Garlic chicken, rice & broccoli bowls","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"chicken-breast-raw","grams":300,"display":"2 small breasts","prep":"raw, cut into strips"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":300,"display":"1 head","prep":"florets"},{"ingredientId":"soy-sauce","grams":16,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"grated"}],"steps":["Cook the rice according to the packet (about 12–15 minutes).","Meanwhile, fry the chicken in the oil over medium-high heat for 6–8 minutes until cooked through.","Add the garlic and broccoli with a splash of water, cover and steam for 3–4 minutes.","Stir in the soy sauce and serve over the rice."],"substitutions":[{"ingredientId":"chicken-breast-raw","alternatives":["tofu-firm","chicken-thigh-raw"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}],"notes":"Packs well for two lunches."}'::jsonb),
  ('red-lentil-soup', 'Red lentil & tomato soup', 'lunch', 4, '{"id":"red-lentil-soup","name":"Red lentil & tomato soup","meal":"lunch","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"lentils-dry","grams":200,"display":"1 cup","prep":"dry, rinsed"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"diced"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"vegetable-stock","grams":800,"display":"800 ml"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"cumin, paprika, salt & pepper"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"}],"steps":["Soften the onion and carrot in the oil for 5 minutes. Add the garlic and spices for 1 minute.","Add the lentils, tomatoes and stock. Bring to the boil, then simmer for 20 minutes until the lentils collapse.","Blend partly or fully, then stir in the lemon juice and season to taste."],"substitutions":[{"ingredientId":"lentils-dry","alternatives":["chickpeas-cooked"]}],"notes":"Freezes well. Stock cubes often contain celery; check the label."}'::jsonb),
  ('tuna-chickpea-salad', 'Tuna & chickpea crunch salad', 'lunch', 2, '{"id":"tuna-chickpea-salad","name":"Tuna & chickpea crunch salad","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"tuna-canned","grams":240,"display":"2 cans","prep":"drained"},{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained, rinsed"},{"ingredientId":"cucumber","grams":150,"display":"½ cucumber","prep":"diced"},{"ingredientId":"tomato","grams":200,"display":"2 tomatoes","prep":"diced"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"diced"},{"ingredientId":"onion","grams":30,"display":"¼ red onion","prep":"finely sliced"},{"ingredientId":"lettuce","grams":80,"display":"2 handfuls"},{"ingredientId":"olive-oil","grams":20,"display":"1½ tbsp"},{"ingredientId":"lemon-juice","grams":20,"display":"1½ tbsp"}],"steps":["Whisk the oil and lemon juice with salt and pepper in a large bowl.","Add the chickpeas, vegetables and onion and toss to coat.","Flake in the tuna, fold gently and serve over the lettuce."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["chicken-breast-cooked","egg"]},{"ingredientId":"chickpeas-cooked","alternatives":["black-beans-cooked"]}]}'::jsonb),
  ('greek-chicken-wraps', 'Chicken wraps with garlic yogurt', 'lunch', 2, '{"id":"greek-chicken-wraps","name":"Chicken wraps with garlic yogurt","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"tortilla-wheat","grams":90,"display":"2 tortillas"},{"ingredientId":"chicken-breast-cooked","grams":160,"display":"160 g","prep":"cooked, sliced"},{"ingredientId":"greek-yogurt-0","grams":80,"display":"⅓ cup"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"grated"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"grated or sliced"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"lettuce","grams":40,"display":"1 handful","prep":"shredded"}],"steps":["Mix the yogurt with the garlic, a pinch of salt and half the cucumber.","Warm the tortillas in a dry pan for 20 seconds each side.","Spread with the yogurt sauce, add lettuce, tomato, the rest of the cucumber and chicken, then roll up tightly."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["tofu-firm","chickpeas-cooked"]},{"ingredientId":"greek-yogurt-0","alternatives":["soy-yogurt","hummus"]}],"notes":"Use leftover roast chicken or chicken from the rice bowls."}'::jsonb),
  ('quinoa-black-bean-bowl', 'Quinoa black bean bowls', 'lunch', 2, '{"id":"quinoa-black-bean-bowl","name":"Quinoa black bean bowls","meal":"lunch","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"quinoa-dry","grams":120,"display":"⅔ cup","prep":"dry, rinsed"},{"ingredientId":"black-beans-cooked","grams":240,"display":"1 can","prep":"drained, rinsed"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"diced"},{"ingredientId":"tomato","grams":120,"display":"1 tomato","prep":"diced"},{"ingredientId":"avocado","grams":100,"display":"⅔ avocado","prep":"sliced"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":3,"display":"cumin, chilli, salt"}],"steps":["Simmer the quinoa in twice its volume of water for 12–15 minutes, then drain.","Warm the beans with the spices and a splash of water for 2 minutes.","Toss the quinoa with the oil and lemon juice, then top with beans, pepper, tomato and avocado."],"substitutions":[{"ingredientId":"quinoa-dry","alternatives":["rice-white-dry"]},{"ingredientId":"black-beans-cooked","alternatives":["chickpeas-cooked","edamame"]}]}'::jsonb),
  ('egg-hummus-rye', 'Egg & hummus open rye sandwiches', 'lunch', 1, '{"id":"egg-hummus-rye","name":"Egg & hummus open rye sandwiches","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":9,"ingredients":[{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"hummus","grams":40,"display":"2½ tbsp"},{"ingredientId":"egg","grams":100,"display":"2 eggs","prep":"hard-boiled"},{"ingredientId":"cucumber","grams":40,"display":"5 cm piece","prep":"sliced"},{"ingredientId":"spinach","grams":15,"display":"a few leaves"}],"steps":["Boil the eggs for 9 minutes, cool in cold water and peel.","Spread the hummus over the rye bread.","Top with spinach, cucumber and sliced egg. Season with pepper."],"substitutions":[{"ingredientId":"egg","alternatives":["tuna-canned","tofu-firm"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread"]}]}'::jsonb),
  ('baked-cod-potatoes-peas', 'Lemon baked cod with potatoes & peas', 'dinner', 2, '{"id":"baked-cod-potatoes-peas","name":"Lemon baked cod with potatoes & peas","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"cod-raw","grams":320,"display":"2 fillets","prep":"raw"},{"ingredientId":"potato-raw","grams":450,"display":"2 medium potatoes","prep":"cut into wedges"},{"ingredientId":"peas-green","grams":160,"display":"1 cup","prep":"frozen"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"dill, salt & pepper"}],"steps":["Heat the oven to 220 °C (200 °C fan). Toss the potato wedges with most of the oil and salt, and roast for 20 minutes.","Push the potatoes aside, add the cod, drizzle with the remaining oil and lemon juice, season, and bake 10–12 minutes until it flakes.","Meanwhile, boil the peas for 3 minutes. Serve together with dill."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["salmon-raw","tofu-firm"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('salmon-sweet-potato-traybake', 'Salmon & sweet potato traybake', 'dinner', 2, '{"id":"salmon-sweet-potato-traybake","name":"Salmon & sweet potato traybake","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"salmon-raw","grams":280,"display":"2 fillets","prep":"raw"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"cubed"},{"ingredientId":"broccoli","grams":250,"display":"1 small head","prep":"florets"},{"ingredientId":"olive-oil","grams":10,"display":"2 tsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":2,"display":"paprika, salt & pepper"}],"steps":["Heat the oven to 200 °C (180 °C fan). Toss the sweet potato with the oil and spices and roast for 15 minutes.","Add the broccoli and salmon to the tray and roast 12–15 minutes more, until the salmon flakes easily.","Finish with lemon juice."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["cod-raw","chicken-breast-raw"]},{"ingredientId":"sweet-potato-raw","alternatives":["potato-raw"]}]}'::jsonb),
  ('beef-bean-chilli', 'Beef & black bean chilli with rice', 'dinner', 4, '{"id":"beef-bean-chilli","name":"Beef & black bean chilli with rice","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":35,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":400,"display":"400 g","prep":"raw"},{"ingredientId":"black-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"diced"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"spices","grams":8,"display":"chilli, cumin, paprika, salt"},{"ingredientId":"rice-white-dry","grams":240,"display":"1¼ cups","prep":"dry"}],"steps":["Brown the mince in a large pan over high heat, breaking it up, for 5 minutes.","Add the onion, pepper and garlic and cook 5 minutes. Stir in the spices for 1 minute.","Add the tomatoes and beans, then simmer uncovered for 25 minutes, stirring now and then.","Cook the rice according to the packet and serve with the chilli."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["lentils-dry","chicken-thigh-raw"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}],"notes":"Freezes well in portions."}'::jsonb),
  ('chicken-thigh-traybake', 'Chicken thigh, potato & carrot traybake', 'dinner', 4, '{"id":"chicken-thigh-traybake","name":"Chicken thigh, potato & carrot traybake","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":40,"ingredients":[{"ingredientId":"chicken-thigh-raw","grams":600,"display":"8 boneless thighs","prep":"raw, skinless"},{"ingredientId":"potato-raw","grams":800,"display":"4 medium potatoes","prep":"chunks"},{"ingredientId":"carrot","grams":300,"display":"5 carrots","prep":"chunks"},{"ingredientId":"onion","grams":200,"display":"2 onions","prep":"wedges"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"smashed"},{"ingredientId":"olive-oil","grams":20,"display":"1½ tbsp"},{"ingredientId":"spices","grams":4,"display":"thyme, paprika, salt & pepper"}],"steps":["Heat the oven to 210 °C (190 °C fan).","Toss everything with the oil and spices on a large tray, keeping the chicken on top.","Roast for 35–40 minutes, turning the vegetables once, until the chicken is cooked through and the potatoes are golden."],"substitutions":[{"ingredientId":"chicken-thigh-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('lentil-bolognese', 'Lentil bolognese', 'dinner', 4, '{"id":"lentil-bolognese","name":"Lentil bolognese","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"lentils-dry","grams":180,"display":"1 cup","prep":"dry, rinsed"},{"ingredientId":"pasta-dry","grams":320,"display":"320 g","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"diced"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"finely diced"},{"ingredientId":"mushrooms","grams":150,"display":"2 cups","prep":"chopped"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"spices","grams":4,"display":"oregano, salt & pepper"}],"steps":["Soften the onion, carrot and mushrooms in the oil for 8 minutes. Add the garlic for 1 minute.","Add the lentils, tomatoes and 300 ml water. Simmer for 25 minutes until the lentils are tender, adding water if it gets dry.","Meanwhile, cook the pasta according to the packet. Season the sauce and serve over the pasta."],"substitutions":[{"ingredientId":"lentils-dry","alternatives":["beef-mince-10-raw"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('tofu-veg-stir-fry', 'Crispy tofu & edamame stir-fry', 'dinner', 2, '{"id":"tofu-veg-stir-fry","name":"Crispy tofu & edamame stir-fry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"tofu-firm","grams":300,"display":"1 block","prep":"pressed, cubed"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":200,"display":"2 cups","prep":"florets"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"carrot","grams":80,"display":"1 large carrot","prep":"thin strips"},{"ingredientId":"edamame","grams":100,"display":"⅔ cup","prep":"shelled"},{"ingredientId":"soy-sauce","grams":24,"display":"1½ tbsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"grated"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"}],"steps":["Cook the rice according to the packet.","Fry the tofu in half the oil over high heat for 6–8 minutes, turning, until golden. Set aside.","Stir-fry the vegetables and edamame in the remaining oil for 4 minutes. Add the garlic for 30 seconds.","Return the tofu, add the soy sauce, toss and serve over the rice."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["chicken-breast-raw","tempeh"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}]}'::jsonb),
  ('garlic-prawn-pasta', 'Garlic prawn & spinach pasta', 'dinner', 2, '{"id":"garlic-prawn-pasta","name":"Garlic prawn & spinach pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"pasta-dry","grams":180,"display":"180 g","prep":"dry"},{"ingredientId":"shrimp-cooked","grams":250,"display":"250 g","prep":"cooked, peeled"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"tomato","grams":200,"display":"2 tomatoes","prep":"chopped"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"sliced"},{"ingredientId":"olive-oil","grams":13.5,"display":"1 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"chilli flakes, salt & pepper"}],"steps":["Cook the pasta according to the packet. Save a cup of the cooking water before draining.","Warm the oil and garlic gently for 1 minute, add the tomatoes and cook for 3 minutes.","Add the prawns and spinach and stir until the spinach wilts and the prawns are hot (2 minutes).","Toss in the pasta with lemon juice and a splash of the pasta water."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["chicken-breast-cooked","tuna-canned"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('chickpea-sweet-potato-curry', 'Chickpea & sweet potato curry', 'dinner', 4, '{"id":"chickpea-sweet-potato-curry","name":"Chickpea & sweet potato curry","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":30,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"sweet-potato-raw","grams":400,"display":"2 medium","prep":"cubed"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"onion","grams":110,"display":"1 onion","prep":"diced"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"spices","grams":8,"display":"curry powder, cumin, salt"},{"ingredientId":"rapeseed-oil","grams":14,"display":"1 tbsp"},{"ingredientId":"rice-white-dry","grams":200,"display":"1 cup","prep":"dry"},{"ingredientId":"soy-yogurt","grams":120,"display":"½ cup","prep":"to serve"}],"steps":["Soften the onion in the oil for 5 minutes, add the garlic and spices for 1 minute.","Add the sweet potato, tomatoes and 250 ml water. Cover and simmer for 15 minutes.","Add the chickpeas and simmer 8 minutes more until the sweet potato is tender. Stir in the spinach.","Serve with rice and a spoon of yogurt."],"substitutions":[{"ingredientId":"soy-yogurt","alternatives":["greek-yogurt-0","skyr-plain"]},{"ingredientId":"chickpeas-cooked","alternatives":["lentils-cooked","tofu-firm"]}]}'::jsonb),
  ('skyr-peanut-apple-dip', 'Peanut skyr dip with apple', 'snack', 1, '{"id":"skyr-peanut-apple-dip","name":"Peanut skyr dip with apple","meal":"snack","servings":1,"prepMinutes":3,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":150,"display":"150 g"},{"ingredientId":"peanut-butter","grams":16,"display":"1 tbsp"},{"ingredientId":"apple","grams":150,"display":"1 small apple","prep":"sliced"}],"steps":["Stir the peanut butter into the skyr until smooth.","Serve with apple slices for dipping."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"peanut-butter","alternatives":["tahini"]}]}'::jsonb),
  ('cottage-cheese-berries', 'Cottage cheese with berries & seeds', 'snack', 1, '{"id":"cottage-cheese-berries","name":"Cottage cheese with berries & seeds","meal":"snack","servings":1,"prepMinutes":2,"cookMinutes":0,"ingredients":[{"ingredientId":"cottage-cheese","grams":150,"display":"⅔ cup"},{"ingredientId":"strawberries","grams":100,"display":"⅔ cup","prep":"sliced"},{"ingredientId":"pumpkin-seeds","grams":9,"display":"1 tbsp"}],"steps":["Spoon the cottage cheese into a bowl.","Top with the strawberries and pumpkin seeds."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","soy-yogurt"]},{"ingredientId":"strawberries","alternatives":["blueberries"]}]}'::jsonb),
  ('roasted-spiced-chickpeas', 'Crunchy roasted chickpeas', 'snack', 3, '{"id":"roasted-spiced-chickpeas","name":"Crunchy roasted chickpeas","meal":"snack","servings":3,"prepMinutes":5,"cookMinutes":30,"ingredients":[{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained, patted dry"},{"ingredientId":"olive-oil","grams":7,"display":"1½ tsp"},{"ingredientId":"spices","grams":3,"display":"smoked paprika, salt"}],"steps":["Heat the oven to 200 °C (180 °C fan). Pat the chickpeas very dry with a towel.","Toss with the oil and spices and spread on a tray in one layer.","Roast for 25–30 minutes, shaking halfway, until crisp. They crisp more as they cool."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["edamame"]}],"notes":"Store in an open container so they stay crunchy."}'::jsonb),
  ('hummus-veg-crispbread', 'Hummus, veg sticks & crispbread', 'snack', 1, '{"id":"hummus-veg-crispbread","name":"Hummus, veg sticks & crispbread","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"hummus","grams":60,"display":"4 tbsp"},{"ingredientId":"carrot","grams":80,"display":"1 large carrot","prep":"sticks"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"sticks"},{"ingredientId":"rye-crispbread","grams":20,"display":"2 crispbreads"},{"ingredientId":"edamame","grams":60,"display":"⅓ cup","prep":"shelled"}],"steps":["Cut the carrot and cucumber into sticks.","Serve with the hummus, edamame and crispbread."],"substitutions":[{"ingredientId":"rye-crispbread","alternatives":["wholewheat-bread"]},{"ingredientId":"hummus","alternatives":["cottage-cheese"]}]}'::jsonb),
  ('skyr-oat-pancakes', 'Skyr & oat pancakes', 'breakfast', 1, '{"id":"skyr-oat-pancakes","name":"Skyr & oat pancakes","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"skyr-plain","grams":150,"display":"150 g"},{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"oats-dry","grams":50,"display":"½ cup","prep":"dry"},{"ingredientId":"banana","grams":60,"display":"½ banana"},{"ingredientId":"rapeseed-oil","grams":4,"display":"1 tsp"},{"ingredientId":"blueberries","grams":50,"display":"⅓ cup","optional":true}],"steps":["Blend or mash the skyr, eggs, oats and banana into a thick batter. Rest it for 2 minutes.","Heat a non-stick pan over medium heat and brush with a little oil.","Spoon in small pancakes and cook about 2 minutes per side until golden and set.","Serve warm with berries on top."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","cottage-cheese"]},{"ingredientId":"blueberries","alternatives":["raspberries","strawberries"]}],"notes":"Keep the pancakes small so they are easy to flip."}'::jsonb),
  ('smoked-salmon-skyr-crispbread', 'Smoked salmon & skyr crispbreads', 'breakfast', 1, '{"id":"smoked-salmon-skyr-crispbread","name":"Smoked salmon & skyr crispbreads","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"rye-crispbread","grams":30,"display":"3 crispbreads"},{"ingredientId":"skyr-plain","grams":100,"display":"100 g"},{"ingredientId":"smoked-salmon","grams":100,"display":"100 g"},{"ingredientId":"cucumber","grams":50,"display":"5 cm piece","prep":"thinly sliced"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dill & black pepper"}],"steps":["Stir the lemon juice, dill and pepper into the skyr.","Spread the skyr over the crispbreads.","Top with cucumber slices and the smoked salmon."],"substitutions":[{"ingredientId":"smoked-salmon","alternatives":["tuna-canned","egg"]},{"ingredientId":"rye-crispbread","alternatives":["rye-bread","rice-cakes"]}]}'::jsonb),
  ('savoury-cottage-cheese-bowl', 'Savoury cottage cheese bowl', 'breakfast', 1, '{"id":"savoury-cottage-cheese-bowl","name":"Savoury cottage cheese bowl","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"cottage-cheese","grams":250,"display":"250 g (about 1 cup)"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"pumpkin-seeds","grams":15,"display":"1½ tbsp"},{"ingredientId":"rye-crispbread","grams":20,"display":"2 crispbreads"},{"ingredientId":"spices","grams":1,"display":"salt, pepper & chilli flakes"}],"steps":["Spoon the cottage cheese into a bowl.","Pile the tomato and cucumber on top and season.","Scatter with pumpkin seeds and eat with the crispbreads."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","greek-yogurt-0"]},{"ingredientId":"rye-crispbread","alternatives":["rice-cakes"]}]}'::jsonb),
