  ('skyr-berry-smoothie', 'Skyr berry smoothie', 'breakfast', 1, '{"id":"skyr-berry-smoothie","name":"Skyr berry smoothie","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":200,"display":"200 g"},{"ingredientId":"milk","grams":200,"display":"200 ml"},{"ingredientId":"banana","grams":100,"display":"1 small banana"},{"ingredientId":"strawberries","grams":100,"display":"⅔ cup","prep":"frozen is fine"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"}],"steps":["Put everything in a blender, milk first.","Blend for 30–60 seconds until smooth. Add a splash more milk if it is too thick.","Pour into a large glass and drink straight away."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]}]}'::jsonb),
  ('berry-smoothie-bowl-vegan', 'Berry smoothie bowl with seeds', 'breakfast', 1, '{"id":"berry-smoothie-bowl-vegan","name":"Berry smoothie bowl with seeds","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"soy-yogurt","grams":200,"display":"200 g"},{"ingredientId":"soy-drink","grams":100,"display":"100 ml"},{"ingredientId":"raspberries","grams":150,"display":"1¼ cups","prep":"frozen"},{"ingredientId":"banana","grams":100,"display":"1 small banana","prep":"frozen if possible"},{"ingredientId":"pumpkin-seeds","grams":15,"display":"1½ tbsp"},{"ingredientId":"chia-seeds","grams":10,"display":"1 tbsp"}],"steps":["Blend the soy yogurt, soy drink, raspberries and banana until thick and smooth.","Spoon into a bowl.","Top with pumpkin and chia seeds."],"substitutions":[{"ingredientId":"soy-yogurt","alternatives":["skyr-plain","greek-yogurt-0"]},{"ingredientId":"raspberries","alternatives":["blueberries","strawberries"]}]}'::jsonb),
  ('shakshuka-for-one', 'Shakshuka for one', 'breakfast', 1, '{"id":"shakshuka-for-one","name":"Shakshuka for one","meal":"breakfast","servings":1,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"egg","grams":150,"display":"3 eggs"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"sliced"},{"ingredientId":"onion","grams":40,"display":"⅓ onion","prep":"sliced"},{"ingredientId":"feta","grams":50,"display":"50 g","prep":"crumbled"},{"ingredientId":"olive-oil","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":2,"display":"cumin, paprika, salt & pepper"},{"ingredientId":"rye-bread","grams":32,"display":"1 slice"}],"steps":["Soften the onion and pepper in the oil in a small frying pan for 4 minutes.","Add the spices and tomatoes and simmer for 3 minutes until slightly thickened.","Make three hollows, crack in the eggs, cover and cook on low for 4–5 minutes until the whites set.","Crumble the feta over and eat from the pan with the rye bread."],"substitutions":[{"ingredientId":"feta","alternatives":["gouda"]},{"ingredientId":"rye-bread","alternatives":["wholewheat-bread","pita-wholewheat"]}]}'::jsonb),
  ('bircher-muesli-batch', 'Skyr Bircher muesli', 'breakfast', 4, '{"id":"bircher-muesli-batch","name":"Skyr Bircher muesli","meal":"breakfast","servings":4,"prepMinutes":10,"cookMinutes":0,"ingredients":[{"ingredientId":"oats-dry","grams":200,"display":"2½ cups","prep":"dry"},{"ingredientId":"skyr-plain","grams":400,"display":"400 g"},{"ingredientId":"milk","grams":400,"display":"400 ml"},{"ingredientId":"apple","grams":360,"display":"2 apples","prep":"grated"},{"ingredientId":"raisins","grams":40,"display":"4 tbsp"},{"ingredientId":"walnuts","grams":40,"display":"6 tbsp","prep":"chopped"},{"ingredientId":"spices","grams":1,"display":"cinnamon"}],"steps":["Mix the oats, milk, skyr, raisins and cinnamon in a large container.","Grate in the apples, skin and all, and stir through.","Cover and chill overnight. Scoop into bowls and top with walnuts."],"substitutions":[{"ingredientId":"milk","alternatives":["soy-drink","oat-drink"]},{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]}],"notes":"Keeps 3 days in the fridge. Add the nuts just before eating so they stay crunchy."}'::jsonb),
  ('tuna-white-bean-salad', 'Tuna & white bean salad', 'lunch', 1, '{"id":"tuna-white-bean-salad","name":"Tuna & white bean salad","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"tuna-canned","grams":120,"display":"1 can","prep":"drained"},{"ingredientId":"white-beans-cooked","grams":120,"display":"½ can","prep":"drained, rinsed"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"chopped"},{"ingredientId":"cucumber","grams":60,"display":"¼ cucumber","prep":"chopped"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Whisk the oil, lemon juice, salt and pepper in a bowl.","Add the beans, tomato, cucumber and spring onion and toss.","Flake the tuna over the top in large pieces."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["sardines-canned","chicken-breast-cooked"]},{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked","kidney-beans-cooked"]}],"notes":"Packs well for work: keep the dressing separate until lunch."}'::jsonb),
  ('chicken-caesar-skyr-wrap', 'Chicken Caesar-style wrap', 'lunch', 1, '{"id":"chicken-caesar-skyr-wrap","name":"Chicken Caesar-style wrap","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"tortilla-wheat","grams":45,"display":"1 tortilla"},{"ingredientId":"chicken-breast-cooked","grams":100,"display":"100 g","prep":"sliced"},{"ingredientId":"lettuce","grams":40,"display":"1 cup","prep":"shredded"},{"ingredientId":"skyr-plain","grams":50,"display":"3 tbsp"},{"ingredientId":"parmesan","grams":10,"display":"2 tbsp","prep":"finely grated"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"mustard","grams":5,"display":"1 tsp"}],"steps":["Stir the skyr, parmesan, lemon juice and mustard into a quick dressing.","Toss the lettuce and chicken in the dressing.","Pile onto the tortilla, fold in the sides and roll up. Cut in half."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["tuna-canned","tofu-firm"]},{"ingredientId":"tortilla-wheat","alternatives":["pita-wholewheat","tortilla-corn"]}]}'::jsonb),
  ('egg-cottage-cheese-rye', 'Egg & cottage cheese open sandwich', 'lunch', 1, '{"id":"egg-cottage-cheese-rye","name":"Egg & cottage cheese open sandwich","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"cottage-cheese","grams":150,"display":"150 g"},{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"},{"ingredientId":"spring-onion","grams":10,"display":"½ spring onion","prep":"sliced"},{"ingredientId":"spices","grams":1,"display":"salt, pepper & paprika"}],"steps":["Boil the eggs for 8 minutes, then cool them in cold water and peel.","Spread the cottage cheese thickly over the rye bread.","Top with tomato, sliced egg and spring onion, then season."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain","hummus"]},{"ingredientId":"rye-bread","alternatives":["rye-crispbread","wholewheat-bread"]}],"notes":"Boil a batch of eggs at the start of the week to make this a 5-minute lunch."}'::jsonb),
