  ('lentil-herb-salad', 'Lemony lentil salad with seeds', 'lunch', 1, '{"id":"lentil-herb-salad","name":"Lemony lentil salad with seeds","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"lentils-cooked","grams":200,"display":"1 cup (½ can)","prep":"drained"},{"ingredientId":"cucumber","grams":80,"display":"¼ cucumber","prep":"diced"},{"ingredientId":"tomato","grams":80,"display":"1 small tomato","prep":"diced"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"pumpkin-seeds","grams":15,"display":"1½ tbsp"},{"ingredientId":"spices","grams":2,"display":"parsley, salt & pepper"}],"steps":["Whisk the lemon juice, oil, salt and pepper in a bowl.","Add the lentils, cucumber, tomato, spring onion and herbs and toss well.","Scatter the pumpkin seeds on top."],"substitutions":[{"ingredientId":"lentils-cooked","alternatives":["chickpeas-cooked","white-beans-cooked"]},{"ingredientId":"pumpkin-seeds","alternatives":["sunflower-seeds"]}],"notes":"Gets better after an hour in the fridge."}'::jsonb),
  ('chicken-quinoa-salad-box', 'Chicken & quinoa salad box', 'lunch', 1, '{"id":"chicken-quinoa-salad-box","name":"Chicken & quinoa salad box","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":0,"ingredients":[{"ingredientId":"quinoa-cooked","grams":150,"display":"¾ cup","prep":"cooked, cooled"},{"ingredientId":"chicken-breast-cooked","grams":120,"display":"120 g","prep":"sliced"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"diced"},{"ingredientId":"feta","grams":30,"display":"30 g","prep":"crumbled"},{"ingredientId":"lemon-juice","grams":10,"display":"2 tsp"},{"ingredientId":"olive-oil","grams":7,"display":"½ tbsp"}],"steps":["Put the spinach in the bottom of a lunch box.","Mix the quinoa with the lemon juice and oil and spoon on top.","Add the pepper, chicken and feta."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["tuna-canned","chickpeas-cooked"]},{"ingredientId":"quinoa-cooked","alternatives":["rice-white-cooked","pasta-cooked"]}]}'::jsonb),
  ('tofu-edamame-noodle-bowl', 'Tofu & edamame noodle bowl', 'lunch', 1, '{"id":"tofu-edamame-noodle-bowl","name":"Tofu & edamame noodle bowl","meal":"lunch","servings":1,"prepMinutes":8,"cookMinutes":8,"ingredients":[{"ingredientId":"tofu-firm","grams":150,"display":"150 g","prep":"cubed"},{"ingredientId":"edamame","grams":80,"display":"½ cup","prep":"thawed"},{"ingredientId":"rice-noodles-cooked","grams":150,"display":"150 g cooked (about 50 g dry)"},{"ingredientId":"carrot","grams":50,"display":"1 small carrot","prep":"grated"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"},{"ingredientId":"lime-juice","grams":10,"display":"2 tsp"}],"steps":["Fry the tofu in the sesame oil over medium-high heat for 6 minutes, turning, until golden.","Add the edamame and soy sauce and toss for 1 minute.","Cook the noodles as the packet says and drain.","Pile the noodles into a bowl with the tofu, carrot and spring onion, then squeeze over the lime."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","chicken-breast-raw"]},{"ingredientId":"rice-noodles-cooked","alternatives":["rice-white-cooked"]}]}'::jsonb),
  ('turkey-lettuce-cups', 'Ginger turkey lettuce cups', 'lunch', 1, '{"id":"turkey-lettuce-cups","name":"Ginger turkey lettuce cups","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":10,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":150,"display":"150 g","prep":"raw"},{"ingredientId":"lettuce","grams":60,"display":"6 leaves"},{"ingredientId":"carrot","grams":40,"display":"½ carrot","prep":"grated"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"ginger","grams":5,"display":"1 tsp","prep":"grated"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"rapeseed-oil","grams":5,"display":"1 tsp"},{"ingredientId":"rice-white-cooked","grams":100,"display":"⅔ cup","prep":"cooked"}],"steps":["Fry the turkey in the oil over high heat for 6–7 minutes, breaking it up, until browned and cooked through.","Stir in the ginger and soy sauce and cook 1 more minute.","Spoon rice and turkey into the lettuce leaves and top with carrot and spring onion."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["chicken-thigh-raw","tofu-firm"]},{"ingredientId":"rice-white-cooked","alternatives":["rice-noodles-cooked","quinoa-cooked"]}]}'::jsonb),
  ('cottage-cheese-veg-pitta', 'Cottage cheese & veg pitta', 'lunch', 1, '{"id":"cottage-cheese-veg-pitta","name":"Cottage cheese & veg pitta","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"pita-wholewheat","grams":64,"display":"1 pitta"},{"ingredientId":"cottage-cheese","grams":150,"display":"150 g"},{"ingredientId":"cucumber","grams":50,"display":"5 cm piece","prep":"diced"},{"ingredientId":"tomato","grams":50,"display":"½ small tomato","prep":"diced"},{"ingredientId":"spinach","grams":20,"display":"a handful"},{"ingredientId":"spices","grams":1,"display":"pepper & chilli flakes"}],"steps":["Warm the pitta briefly and cut it open into a pocket.","Mix the cottage cheese with the cucumber, tomato and seasoning.","Line the pitta with spinach and spoon in the filling."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["hummus","skyr-plain"]},{"ingredientId":"pita-wholewheat","alternatives":["tortilla-wheat","wholewheat-bread"]}]}'::jsonb),
  ('white-bean-spinach-soup', 'White bean, tomato & spinach soup', 'lunch', 2, '{"id":"white-bean-spinach-soup","name":"White bean, tomato & spinach soup","meal":"lunch","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"white-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"vegetable-stock","grams":500,"display":"500 ml"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"chopped"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":2,"display":"dried thyme, salt & pepper"}],"steps":["Soften the onion and garlic in the oil for 4 minutes.","Add the beans, tomatoes, stock and thyme and simmer for 10 minutes.","Mash some of the beans against the side of the pan to thicken the soup.","Stir in the spinach until wilted and season to taste."],"substitutions":[{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked","kidney-beans-cooked"]},{"ingredientId":"spinach","alternatives":["cabbage"]}],"notes":"Freezes well. Many stock cubes contain celery: check the label if that matters to you."}'::jsonb),
  ('chicken-egg-fried-rice', 'Chicken & egg fried rice', 'lunch', 1, '{"id":"chicken-egg-fried-rice","name":"Chicken & egg fried rice","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"rice-white-cooked","grams":200,"display":"1¼ cups","prep":"cooked, cold"},{"ingredientId":"chicken-breast-cooked","grams":80,"display":"80 g","prep":"diced"},{"ingredientId":"egg","grams":100,"display":"2 eggs","prep":"beaten"},{"ingredientId":"peas-green","grams":80,"display":"½ cup","prep":"frozen"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"},{"ingredientId":"soy-sauce","grams":10,"display":"2 tsp"},{"ingredientId":"rapeseed-oil","grams":7,"display":"½ tbsp"}],"steps":["Heat the oil in a large pan or wok over high heat and cook the peas for 1 minute.","Push them aside, pour in the eggs and scramble until just set.","Add the rice and chicken and stir-fry for 3–4 minutes until piping hot.","Season with soy sauce and scatter with spring onion."],"substitutions":[{"ingredientId":"chicken-breast-cooked","alternatives":["shrimp-cooked","tofu-firm"]},{"ingredientId":"rice-white-cooked","alternatives":["quinoa-cooked"]}],"notes":"Day-old rice fries best. Cool cooked rice quickly and keep it in the fridge for no more than a day."}'::jsonb),
  ('tuna-melt-rye', 'Open tuna melt on rye', 'lunch', 1, '{"id":"tuna-melt-rye","name":"Open tuna melt on rye","meal":"lunch","servings":1,"prepMinutes":5,"cookMinutes":4,"ingredients":[{"ingredientId":"rye-bread","grams":64,"display":"2 slices"},{"ingredientId":"tuna-canned","grams":120,"display":"1 can","prep":"drained"},{"ingredientId":"skyr-plain","grams":30,"display":"2 tbsp"},{"ingredientId":"gouda","grams":20,"display":"1 slice"},{"ingredientId":"spring-onion","grams":10,"display":"½ spring onion","prep":"sliced"},{"ingredientId":"tomato","grams":60,"display":"½ tomato","prep":"sliced"}],"steps":["Heat the grill. Mix the tuna with the skyr and spring onion.","Toast the rye bread lightly, then spread with the tuna mix.","Top with tomato and cheese and grill for 3–4 minutes until bubbling."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["sardines-canned","chicken-breast-cooked"]},{"ingredientId":"gouda","alternatives":["mozzarella-light"]}]}'::jsonb),
  ('haddock-potatoes-green-beans', 'Pan-fried haddock, potatoes & green beans', 'dinner', 2, '{"id":"haddock-potatoes-green-beans","name":"Pan-fried haddock, potatoes & green beans","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":20,"ingredients":[{"ingredientId":"haddock-raw","grams":300,"display":"2 fillets (300 g)"},{"ingredientId":"potato-raw","grams":400,"display":"400 g","prep":"halved"},{"ingredientId":"green-beans","grams":200,"display":"2 cups","prep":"trimmed"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"salt, pepper & dill"}],"steps":["Boil the potatoes in salted water for 15 minutes, adding the green beans for the last 4.","Pat the haddock dry and season with salt and pepper.","Fry in the oil over medium-high heat for 3 minutes, flip gently and cook 2 minutes more until it flakes.","Drain the vegetables and serve with the fish, a squeeze of lemon and dill."],"substitutions":[{"ingredientId":"haddock-raw","alternatives":["cod-raw","salmon-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw","rice-white-dry"]}]}'::jsonb),
  ('lamb-couscous-skyr', 'Spiced lamb couscous with skyr', 'dinner', 2, '{"id":"lamb-couscous-skyr","name":"Spiced lamb couscous with skyr","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"lamb-mince-raw","grams":250,"display":"250 g","prep":"raw"},{"ingredientId":"couscous-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"zucchini","grams":150,"display":"¾ courgette","prep":"diced"},{"ingredientId":"onion","grams":80,"display":"¾ onion","prep":"chopped"},{"ingredientId":"tomatoes-canned","grams":200,"display":"½ can"},{"ingredientId":"skyr-plain","grams":100,"display":"100 g"},{"ingredientId":"spices","grams":4,"display":"cumin, cinnamon, salt & pepper"}],"steps":["Brown the lamb in a dry pan over high heat for 5 minutes. Spoon off excess fat.","Add the onion, courgette and spices and cook 4 minutes.","Stir in the tomatoes and simmer for 5 minutes.","Meanwhile pour 160 ml boiling water over the couscous, cover for 5 minutes and fluff.","Serve the lamb over the couscous with a spoonful of skyr."],"substitutions":[{"ingredientId":"lamb-mince-raw","alternatives":["beef-mince-10-raw","turkey-mince-raw"]},{"ingredientId":"couscous-dry","alternatives":["quinoa-dry","rice-white-dry"]}]}'::jsonb),
  ('cod-white-bean-tomato', 'One-pan cod with tomato & white beans', 'dinner', 2, '{"id":"cod-white-bean-tomato","name":"One-pan cod with tomato & white beans","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"cod-raw","grams":300,"display":"2 fillets (300 g)"},{"ingredientId":"white-beans-cooked","grams":240,"display":"1 can","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"sliced"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":2,"display":"paprika, salt & pepper"}],"steps":["Warm the oil and garlic in a wide pan for 1 minute without letting it brown.","Add the tomatoes, beans and paprika and simmer for 5 minutes.","Season the cod, nestle it into the sauce, cover and cook on low for 7–8 minutes until it flakes.","Lift out the fish, stir the spinach into the sauce until wilted and serve together."],"substitutions":[{"ingredientId":"cod-raw","alternatives":["haddock-raw","salmon-raw"]},{"ingredientId":"white-beans-cooked","alternatives":["chickpeas-cooked"]}]}'::jsonb),
  ('turkey-bolognese-batch', 'Turkey bolognese', 'dinner', 4, '{"id":"turkey-bolognese-batch","name":"Turkey bolognese","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"turkey-mince-raw","grams":500,"display":"500 g","prep":"raw"},{"ingredientId":"pasta-dry","grams":320,"display":"320 g","prep":"dry"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"chopped"},{"ingredientId":"carrot","grams":120,"display":"2 carrots","prep":"grated"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":4,"display":"oregano, salt & pepper"}],"steps":["Soften the onion, carrot and garlic in the oil for 5 minutes.","Add the turkey and cook over high heat, breaking it up, until no longer pink.","Stir in the tomatoes and oregano and simmer for 15–20 minutes until thick.","Cook the pasta as the packet says, drain and serve with the sauce."],"substitutions":[{"ingredientId":"turkey-mince-raw","alternatives":["beef-mince-10-raw","lentils-dry"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}],"notes":"The sauce freezes well in portions for up to 3 months."}'::jsonb),
  ('soy-ginger-salmon-rice', 'Soy-ginger salmon with rice & broccoli', 'dinner', 2, '{"id":"soy-ginger-salmon-rice","name":"Soy-ginger salmon with rice & broccoli","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"salmon-raw","grams":260,"display":"2 fillets (260 g)"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":250,"display":"1 small head","prep":"florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"ginger","grams":10,"display":"1½ tbsp","prep":"grated"},{"ingredientId":"honey","grams":10,"display":"½ tbsp"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"}],"steps":["Start the rice cooking. Heat the oven to 200 °C (180 °C fan).","Mix the soy sauce, ginger and honey and brush over the salmon on a lined tray.","Roast for 12 minutes. Steam or boil the broccoli for the last 4–5 minutes of the rice.","Serve the salmon on the rice with the broccoli and spring onion."],"substitutions":[{"ingredientId":"salmon-raw","alternatives":["cod-raw","tofu-firm"]},{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]}]}'::jsonb),
  ('pork-noodle-stir-fry', 'Pork & broccoli noodle stir-fry', 'dinner', 2, '{"id":"pork-noodle-stir-fry","name":"Pork & broccoli noodle stir-fry","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":8,"ingredients":[{"ingredientId":"pork-tenderloin-raw","grams":300,"display":"300 g","prep":"thinly sliced"},{"ingredientId":"rice-noodles-cooked","grams":300,"display":"300 g cooked (about 100 g dry)"},{"ingredientId":"bell-pepper","grams":120,"display":"1 pepper","prep":"sliced"},{"ingredientId":"broccoli","grams":150,"display":"1½ cups","prep":"small florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"ginger","grams":10,"display":"1½ tbsp","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"rapeseed-oil","grams":10,"display":"¾ tbsp"}],"steps":["Prepare the noodles as the packet says and drain.","Stir-fry the pork in half the oil over high heat for 3 minutes, then tip onto a plate.","Add the rest of the oil, the broccoli, pepper, garlic and ginger and stir-fry for 3 minutes.","Return the pork with the noodles and soy sauce and toss until hot."],"substitutions":[{"ingredientId":"pork-tenderloin-raw","alternatives":["chicken-breast-raw","tofu-firm"]},{"ingredientId":"soy-sauce","alternatives":["lime-juice"]}]}'::jsonb),
  ('chicken-fajitas-skyr', 'Chicken fajitas with skyr', 'dinner', 2, '{"id":"chicken-fajitas-skyr","name":"Chicken fajitas with skyr","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":10,"ingredients":[{"ingredientId":"chicken-breast-raw","grams":300,"display":"2 breasts (300 g)","prep":"sliced"},{"ingredientId":"tortilla-wheat","grams":180,"display":"4 tortillas"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"sliced"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"sliced"},{"ingredientId":"skyr-plain","grams":100,"display":"100 g"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"rapeseed-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":5,"display":"paprika, cumin, chilli & salt"}],"steps":["Toss the chicken with the spices.","Fry the pepper and onion in half the oil over high heat for 4 minutes, then push aside.","Add the remaining oil and the chicken and cook 5–6 minutes until cooked through. Squeeze over the lime.","Warm the tortillas and fill with chicken, vegetables and a spoon of skyr."],"substitutions":[{"ingredientId":"chicken-breast-raw","alternatives":["shrimp-cooked","tofu-firm"]},{"ingredientId":"tortilla-wheat","alternatives":["tortilla-corn"]},{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]}]}'::jsonb),
  ('prawn-tacos-cabbage', 'Prawn tacos with crunchy cabbage', 'dinner', 2, '{"id":"prawn-tacos-cabbage","name":"Prawn tacos with crunchy cabbage","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":5,"ingredients":[{"ingredientId":"shrimp-cooked","grams":200,"display":"200 g"},{"ingredientId":"tortilla-corn","grams":104,"display":"4 corn tortillas"},{"ingredientId":"cabbage","grams":100,"display":"1 cup","prep":"finely shredded"},{"ingredientId":"avocado","grams":70,"display":"½ avocado","prep":"sliced"},{"ingredientId":"skyr-plain","grams":60,"display":"4 tbsp"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"chilli, garlic powder & salt"}],"steps":["Toss the cabbage with half the lime juice and a pinch of salt.","Warm the prawns in a hot pan with the spices for 2 minutes.","Stir the remaining lime juice into the skyr.","Warm the tortillas and fill with cabbage, prawns, avocado and the lime skyr."],"substitutions":[{"ingredientId":"shrimp-cooked","alternatives":["cod-raw","chicken-breast-cooked"]},{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]}]}'::jsonb),
  ('red-lentil-dal-batch', 'Red lentil dal with rice', 'dinner', 4, '{"id":"red-lentil-dal-batch","name":"Red lentil dal with rice","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"lentils-dry","grams":300,"display":"1½ cups","prep":"red, rinsed"},{"ingredientId":"tomatoes-canned","grams":400,"display":"1 can"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"chopped"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"ginger","grams":15,"display":"2½ tbsp","prep":"grated"},{"ingredientId":"vegetable-stock","grams":750,"display":"750 ml"},{"ingredientId":"rice-white-dry","grams":240,"display":"1¼ cups","prep":"dry"},{"ingredientId":"spices","grams":6,"display":"curry powder, turmeric, salt"}],"steps":["Soften the onion, garlic and ginger in a splash of the stock for 5 minutes.","Stir in the spices, then add the lentils, tomatoes and remaining stock.","Simmer for 20 minutes, stirring now and then, until the lentils break down.","Cook the rice while the dal simmers and serve together."],"substitutions":[{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]},{"ingredientId":"tomatoes-canned","alternatives":["tomato"]}],"notes":"Thickens as it cools; loosen with water when reheating. Freezes well."}'::jsonb),
  ('peanut-tofu-green-beans', 'Peanut tofu with green beans & rice', 'dinner', 2, '{"id":"peanut-tofu-green-beans","name":"Peanut tofu with green beans & rice","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":15,"ingredients":[{"ingredientId":"tofu-firm","grams":300,"display":"300 g","prep":"pressed, cubed"},{"ingredientId":"green-beans","grams":200,"display":"2 cups","prep":"trimmed, halved"},{"ingredientId":"peanut-butter","grams":32,"display":"2 tbsp"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"lime-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"grated"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"rapeseed-oil","grams":10,"display":"¾ tbsp"}],"steps":["Start the rice. Whisk the peanut butter, soy sauce, lime, garlic and 3 tbsp hot water into a sauce.","Fry the tofu in the oil over medium-high heat for 8 minutes until golden on most sides.","Add the green beans and a splash of water, cover and steam for 4 minutes.","Pour in the sauce, toss for 1 minute and serve over the rice."],"substitutions":[{"ingredientId":"tofu-firm","alternatives":["tempeh","chicken-breast-raw"]},{"ingredientId":"peanut-butter","alternatives":["tahini"]}]}'::jsonb),
  ('two-bean-chilli-batch', 'Two-bean chilli', 'dinner', 4, '{"id":"two-bean-chilli-batch","name":"Two-bean chilli","meal":"dinner","servings":4,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"kidney-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"black-beans-cooked","grams":480,"display":"2 cans","prep":"drained"},{"ingredientId":"tomatoes-canned","grams":800,"display":"2 cans"},{"ingredientId":"onion","grams":150,"display":"1 large onion","prep":"chopped"},{"ingredientId":"bell-pepper","grams":150,"display":"1 large pepper","prep":"diced"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"rice-white-dry","grams":240,"display":"1¼ cups","prep":"dry"},{"ingredientId":"spices","grams":8,"display":"chilli, cumin, smoked paprika, salt"}],"steps":["Soften the onion, pepper and garlic in a large pan with a splash of water for 5 minutes.","Add the spices and stir for 1 minute.","Add the tomatoes and both beans and simmer for 20 minutes until thick.","Cook the rice and serve with the chilli."],"substitutions":[{"ingredientId":"rice-white-dry","alternatives":["quinoa-dry"]},{"ingredientId":"kidney-beans-cooked","alternatives":["lentils-cooked","chickpeas-cooked"]}],"notes":"Freezes well. Top with skyr or avocado if you like."}'::jsonb),
  ('cauliflower-chickpea-traybake', 'Roast cauliflower & chickpeas with tahini', 'dinner', 2, '{"id":"cauliflower-chickpea-traybake","name":"Roast cauliflower & chickpeas with tahini","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":25,"ingredients":[{"ingredientId":"cauliflower","grams":400,"display":"1 small head","prep":"florets"},{"ingredientId":"chickpeas-cooked","grams":240,"display":"1 can","prep":"drained, dried"},{"ingredientId":"onion","grams":100,"display":"1 red onion","prep":"wedges"},{"ingredientId":"olive-oil","grams":15,"display":"1 tbsp"},{"ingredientId":"tahini","grams":30,"display":"2 tbsp"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"spices","grams":4,"display":"cumin, paprika, salt"}],"steps":["Heat the oven to 220 °C (200 °C fan).","Toss the cauliflower, chickpeas and onion with the oil and spices on a large tray.","Roast for 25 minutes, turning once, until browned at the edges.","Whisk the tahini with the lemon juice and 2–3 tbsp water. Toss the tray with the spinach and drizzle with the sauce."],"substitutions":[{"ingredientId":"chickpeas-cooked","alternatives":["white-beans-cooked"]},{"ingredientId":"cauliflower","alternatives":["broccoli","sweet-potato-raw"]}]}'::jsonb),
  ('lemon-chicken-couscous', 'Lemon chicken couscous with cucumber skyr', 'dinner', 2, '{"id":"lemon-chicken-couscous","name":"Lemon chicken couscous with cucumber skyr","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":12,"ingredients":[{"ingredientId":"chicken-breast-raw","grams":300,"display":"2 breasts (300 g)"},{"ingredientId":"couscous-dry","grams":120,"display":"⅔ cup","prep":"dry"},{"ingredientId":"cucumber","grams":100,"display":"⅓ cucumber","prep":"grated"},{"ingredientId":"skyr-plain","grams":150,"display":"150 g"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"garlic","grams":3,"display":"1 clove","prep":"grated"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":3,"display":"oregano, salt & pepper"}],"steps":["Flatten the chicken slightly, rub with half the oil, oregano, salt and pepper.","Cook in a hot pan for 5–6 minutes per side until cooked through. Rest, then slice.","Pour 160 ml boiling water over the couscous with the rest of the oil and half the lemon juice; cover for 5 minutes.","Squeeze the grated cucumber, mix it into the skyr with the garlic and remaining lemon, and serve with the chicken and couscous."],"substitutions":[{"ingredientId":"chicken-breast-raw","alternatives":["chicken-thigh-raw","salmon-raw"]},{"ingredientId":"couscous-dry","alternatives":["quinoa-dry","rice-white-dry"]}]}'::jsonb),
  ('haddock-potato-hash', 'Creamy haddock & potato hash', 'dinner', 2, '{"id":"haddock-potato-hash","name":"Creamy haddock & potato hash","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"haddock-raw","grams":300,"display":"300 g"},{"ingredientId":"potato-raw","grams":400,"display":"400 g","prep":"peeled, chunks"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"finely chopped"},{"ingredientId":"milk","grams":150,"display":"150 ml"},{"ingredientId":"butter","grams":15,"display":"1 tbsp"},{"ingredientId":"spices","grams":2,"display":"white pepper, salt & chives"}],"steps":["Boil the potatoes for 15 minutes until tender, then drain.","Meanwhile poach the haddock in the milk in a covered pan for 6–7 minutes. Lift out the fish and keep the milk.","Soften the onion in the butter, add the potatoes and some of the milk and mash roughly.","Flake in the fish, fold gently, season well and finish with chives."],"substitutions":[{"ingredientId":"haddock-raw","alternatives":["cod-raw"]},{"ingredientId":"milk","alternatives":["oat-drink","soy-drink"]}],"notes":"Inspired by Icelandic fish stew. Lovely with buttered rye bread on the side."}'::jsonb),
  ('lamb-cabbage-skillet', 'Lamb, cabbage & potato skillet', 'dinner', 2, '{"id":"lamb-cabbage-skillet","name":"Lamb, cabbage & potato skillet","meal":"dinner","servings":2,"prepMinutes":10,"cookMinutes":20,"ingredients":[{"ingredientId":"lamb-mince-raw","grams":300,"display":"300 g","prep":"raw"},{"ingredientId":"cabbage","grams":300,"display":"¼ cabbage","prep":"shredded"},{"ingredientId":"potato-raw","grams":300,"display":"2 small potatoes","prep":"small cubes"},{"ingredientId":"carrot","grams":100,"display":"1½ carrots","prep":"sliced"},{"ingredientId":"onion","grams":100,"display":"1 onion","prep":"sliced"},{"ingredientId":"vegetable-stock","grams":200,"display":"200 ml"},{"ingredientId":"spices","grams":3,"display":"thyme, salt & pepper"}],"steps":["Brown the lamb in a large deep pan for 5 minutes and spoon off most of the fat.","Add the potato, carrot and onion and cook 3 minutes.","Pour in the stock, cover and simmer for 8 minutes.","Stir in the cabbage, cover again and cook 5 minutes more until everything is tender. Season."],"substitutions":[{"ingredientId":"lamb-mince-raw","alternatives":["beef-mince-10-raw","turkey-mince-raw"]},{"ingredientId":"potato-raw","alternatives":["sweet-potato-raw"]}]}'::jsonb),
  ('mushroom-spinach-pasta', 'Creamy mushroom & spinach pasta', 'dinner', 2, '{"id":"mushroom-spinach-pasta","name":"Creamy mushroom & spinach pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"pasta-dry","grams":160,"display":"160 g","prep":"dry"},{"ingredientId":"mushrooms","grams":200,"display":"3 cups","prep":"sliced"},{"ingredientId":"spinach","grams":100,"display":"3 large handfuls"},{"ingredientId":"cottage-cheese","grams":200,"display":"200 g"},{"ingredientId":"parmesan","grams":30,"display":"6 tbsp","prep":"grated"},{"ingredientId":"garlic","grams":6,"display":"2 cloves","prep":"chopped"},{"ingredientId":"olive-oil","grams":10,"display":"¾ tbsp"},{"ingredientId":"spices","grams":2,"display":"black pepper & nutmeg"}],"steps":["Cook the pasta as the packet says. Keep a mug of the cooking water.","Fry the mushrooms in the oil over high heat for 5 minutes, add the garlic for 1 minute.","Blend or whisk the cottage cheese and parmesan with a splash of pasta water until smooth.","Toss the pasta with the mushrooms, spinach and sauce off the heat, loosening with more water. Season."],"substitutions":[{"ingredientId":"cottage-cheese","alternatives":["skyr-plain"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}],"notes":"Keep the pan off the heat when adding the sauce so it stays smooth."}'::jsonb),
  ('tempeh-broccoli-rice', 'Maple-soy tempeh with broccoli rice', 'dinner', 2, '{"id":"tempeh-broccoli-rice","name":"Maple-soy tempeh with broccoli rice","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":15,"ingredients":[{"ingredientId":"tempeh","grams":250,"display":"250 g","prep":"sliced"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":200,"display":"2 cups","prep":"florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"maple-syrup","grams":10,"display":"½ tbsp"},{"ingredientId":"ginger","grams":5,"display":"1 tsp","prep":"grated"},{"ingredientId":"sesame-oil","grams":5,"display":"1 tsp"}],"steps":["Cook the rice, adding the broccoli for the last 4 minutes to steam on top.","Fry the tempeh in the sesame oil for 3 minutes per side until golden.","Mix the soy sauce, maple syrup and ginger, pour into the pan and let it bubble and coat the tempeh.","Serve over the rice and broccoli."],"substitutions":[{"ingredientId":"tempeh","alternatives":["tofu-firm","chicken-breast-raw"]},{"ingredientId":"maple-syrup","alternatives":["honey"]}]}'::jsonb),
  ('beef-broccoli-rice', 'Garlic beef & broccoli rice bowl', 'dinner', 2, '{"id":"beef-broccoli-rice","name":"Garlic beef & broccoli rice bowl","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"beef-mince-10-raw","grams":300,"display":"300 g","prep":"raw"},{"ingredientId":"rice-white-dry","grams":150,"display":"¾ cup","prep":"dry"},{"ingredientId":"broccoli","grams":250,"display":"1 small head","prep":"small florets"},{"ingredientId":"soy-sauce","grams":20,"display":"1¼ tbsp"},{"ingredientId":"garlic","grams":9,"display":"3 cloves","prep":"chopped"},{"ingredientId":"ginger","grams":5,"display":"1 tsp","prep":"grated"},{"ingredientId":"spring-onion","grams":15,"display":"1 spring onion","prep":"sliced"}],"steps":["Start the rice.","Brown the beef in a hot pan for 5 minutes, breaking it up. Add the garlic and ginger for 1 minute.","Add the broccoli and 3 tbsp water, cover and cook 4 minutes until just tender.","Stir in the soy sauce and serve over rice with spring onion."],"substitutions":[{"ingredientId":"beef-mince-10-raw","alternatives":["turkey-mince-raw","lentils-dry"]},{"ingredientId":"soy-sauce","alternatives":["lime-juice"]}]}'::jsonb),
  ('tuna-pea-lemon-pasta', 'Lemony tuna & pea pasta', 'dinner', 2, '{"id":"tuna-pea-lemon-pasta","name":"Lemony tuna & pea pasta","meal":"dinner","servings":2,"prepMinutes":5,"cookMinutes":12,"ingredients":[{"ingredientId":"pasta-dry","grams":160,"display":"160 g","prep":"dry"},{"ingredientId":"tuna-canned","grams":240,"display":"2 cans","prep":"drained"},{"ingredientId":"peas-green","grams":150,"display":"1 cup","prep":"frozen"},{"ingredientId":"spinach","grams":60,"display":"2 handfuls"},{"ingredientId":"lemon-juice","grams":15,"display":"1 tbsp"},{"ingredientId":"olive-oil","grams":15,"display":"1 tbsp"},{"ingredientId":"parmesan","grams":20,"display":"4 tbsp","prep":"grated"},{"ingredientId":"spices","grams":1,"display":"black pepper & chilli flakes"}],"steps":["Cook the pasta, adding the peas for the last 2 minutes.","Drain, keeping a little water, and return to the pan.","Stir through the spinach, tuna, oil, lemon juice and a splash of water until glossy.","Serve topped with parmesan, pepper and chilli."],"substitutions":[{"ingredientId":"tuna-canned","alternatives":["salmon-raw","chickpeas-cooked"]},{"ingredientId":"pasta-dry","alternatives":["rice-white-dry"]}]}'::jsonb),
  ('mozzarella-pitta-pizzas', 'Mushroom & mozzarella pitta pizzas', 'dinner', 1, '{"id":"mozzarella-pitta-pizzas","name":"Mushroom & mozzarella pitta pizzas","meal":"dinner","servings":1,"prepMinutes":5,"cookMinutes":10,"ingredients":[{"ingredientId":"pita-wholewheat","grams":128,"display":"2 pittas"},{"ingredientId":"tomatoes-canned","grams":100,"display":"¼ can","prep":"drained a little"},{"ingredientId":"mozzarella-light","grams":125,"display":"1 ball","prep":"torn"},{"ingredientId":"mushrooms","grams":80,"display":"1 cup","prep":"sliced"},{"ingredientId":"spinach","grams":30,"display":"1 large handful"},{"ingredientId":"spices","grams":1,"display":"oregano & black pepper"}],"steps":["Heat the oven to 220 °C (200 °C fan).","Spread the tomatoes over the pittas and sprinkle with oregano.","Top with mushrooms and mozzarella and bake on a tray for 8–10 minutes until bubbling.","Scatter the spinach on top to wilt slightly before eating."],"substitutions":[{"ingredientId":"mozzarella-light","alternatives":["gouda","feta"]},{"ingredientId":"pita-wholewheat","alternatives":["tortilla-wheat"]}]}'::jsonb),
  ('skyr-raspberry-cocoa', 'Skyr with raspberries & cocoa', 'snack', 1, '{"id":"skyr-raspberry-cocoa","name":"Skyr with raspberries & cocoa","meal":"snack","servings":1,"prepMinutes":2,"cookMinutes":0,"ingredients":[{"ingredientId":"skyr-plain","grams":200,"display":"200 g"},{"ingredientId":"raspberries","grams":80,"display":"⅔ cup"},{"ingredientId":"cocoa-powder","grams":5,"display":"1 tbsp"},{"ingredientId":"maple-syrup","grams":7,"display":"1 tsp","optional":true}],"steps":["Stir the cocoa into the skyr until smooth.","Top with the raspberries and a little maple syrup if you like."],"substitutions":[{"ingredientId":"skyr-plain","alternatives":["greek-yogurt-0","soy-yogurt"]},{"ingredientId":"raspberries","alternatives":["strawberries","blueberries"]}]}'::jsonb),
