  ('smoked-salmon-cucumber-bites', 'Smoked salmon cucumber bites', 'snack', 1, '{"id":"smoked-salmon-cucumber-bites","name":"Smoked salmon cucumber bites","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":0,"ingredients":[{"ingredientId":"cucumber","grams":120,"display":"⅓ cucumber","prep":"thick slices"},{"ingredientId":"smoked-salmon","grams":60,"display":"60 g"},{"ingredientId":"skyr-plain","grams":40,"display":"2½ tbsp"},{"ingredientId":"lemon-juice","grams":5,"display":"1 tsp"},{"ingredientId":"spices","grams":1,"display":"dill & pepper"}],"steps":["Mix the skyr with lemon juice, dill and pepper.","Put a small spoonful on each cucumber slice.","Top with a folded piece of smoked salmon."],"substitutions":[{"ingredientId":"smoked-salmon","alternatives":["shrimp-cooked","tuna-canned"]},{"ingredientId":"skyr-plain","alternatives":["cottage-cheese"]}]}'::jsonb),
  ('boiled-eggs-veg-hummus', 'Boiled eggs, veg sticks & hummus', 'snack', 1, '{"id":"boiled-eggs-veg-hummus","name":"Boiled eggs, veg sticks & hummus","meal":"snack","servings":1,"prepMinutes":5,"cookMinutes":8,"ingredients":[{"ingredientId":"egg","grams":100,"display":"2 eggs"},{"ingredientId":"carrot","grams":80,"display":"1 large carrot","prep":"sticks"},{"ingredientId":"bell-pepper","grams":60,"display":"½ pepper","prep":"strips"},{"ingredientId":"hummus","grams":30,"display":"2 tbsp"},{"ingredientId":"spices","grams":1,"display":"salt & pepper"}],"steps":["Boil the eggs for 8 minutes, cool in cold water and peel.","Cut the carrot and pepper into sticks.","Halve the eggs, season and serve with the veg and hummus."],"substitutions":[{"ingredientId":"hummus","alternatives":["cottage-cheese"]},{"ingredientId":"bell-pepper","alternatives":["cucumber"]}],"notes":"Boiled eggs keep 5 days in the fridge in their shells."}'::jsonb),
